begin;
\ir fixtures/clinical.sql
create function pg_temp.ob(action text,n integer,ver integer,k integer,input jsonb default '{}')returns jsonb language sql as $$select public.doctor_outbox_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(n),ver,action,input,pg_temp.id(k))$$;
create function pg_temp.oi()returns jsonb language sql as $$select jsonb_build_object('intent',jsonb_build_object('contact_id',pg_temp.id(6100),'contact_version',1,'purpose','appointment_reminder','consent_version',1,'guardian_version',null),'expires_at',clock_timestamp()+interval '1 day','template','appointment_reminder_v1','parameters','{}'::jsonb)$$;
select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(6100),0,'create_contact','{"channel":"sms","destination":"+15550001234","recipient_kind":"patient","guardian_id":null}',pg_temp.id(6101));
select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(6102),0,'grant_consent',jsonb_build_object('contact_id',pg_temp.id(6100),'contact_version',1,'purpose','appointment_reminder','source_ref','Synthetic explicit consent','source_day',(clock_timestamp()at time zone'Etc/UTC'-interval'1 minute')::date,'source_minute',extract(hour from clock_timestamp()at time zone'Etc/UTC'-interval'1 minute')::integer*60+extract(minute from clock_timestamp()at time zone'Etc/UTC'-interval'1 minute')::integer,'location_version',1),pg_temp.id(6103));
select pg_temp.put('enqueue',pg_temp.oi());
select is(pg_temp.ob('enqueue',6200,0,6201,pg_temp.v('enqueue'))->>'state','queued','C01: persisted neutral queued intent');
select is(pg_temp.ob('enqueue',6200,0,6201,pg_temp.v('enqueue'))->>'version','1','C01: exact idempotent replay');
select throws_ok($$select pg_temp.ob('enqueue',6200,0,6201,pg_temp.v('enqueue')||'{"template":"marketing_v1"}')$$,'22023','DOCTOR_OUTBOX_INVALID','purpose and template cannot disagree');
select throws_ok($$select pg_temp.ob('enqueue',6202,0,6203,pg_temp.v('enqueue')||'{"parameters":{"body":"private"}}')$$,'22023','DOCTOR_OUTBOX_INVALID','message bodies cannot enter outbox');
select pg_temp.put('claim',pg_temp.ob('claim',6200,1,6204));
select is(pg_temp.v('claim')->>'state','claimed','C02: separate leased claim');
select throws_ok($$select pg_temp.ob('claim',6200,1,6205)$$,'40001','DOCTOR_OUTBOX_CONFLICT','competing claim rejected');
select throws_ok($$select pg_temp.ob('accept',6200,2,6206,jsonb_build_object('claim_token',pg_temp.id(999)))$$,'42501','DOCTOR_ACCESS_DENIED','forged lease token denied');
select pg_temp.put('accepted',pg_temp.ob('accept',6200,2,6207,jsonb_build_object('claim_token',pg_temp.v('claim')->>'claim_token')));
select is(pg_temp.v('accepted')->>'state','claimed','acceptance is not acknowledgement or delivery');
reset role;
select is((select count(*)::integer from doctor_private.synthetic_message_acceptances where message_id=pg_temp.id(6200)),1,'acceptance persisted independently');
select ok((select acknowledged_at is null and delivered_at is null from doctor_private.synthetic_message_acceptances where message_id=pg_temp.id(6200)),'crash boundary retains no invented ack or delivery');
update public.message_outbox set lease_until=clock_timestamp()-interval '1 second'where id=pg_temp.id(6200);
set local role authenticated;
select is(pg_temp.ob('reconcile',6200,3,6208)->>'state','unknown','expired lease first becomes unknown');
select is(pg_temp.ob('reconcile',6200,4,6209)->>'state','sent','known acceptance reconciles only to sent');
select throws_ok($$select pg_temp.ob('claim',6200,5,6210)$$,'40001','DOCTOR_OUTBOX_CONFLICT','reconciliation cannot resend');
select throws_ok($$select pg_temp.ob('deliver',6200,5,6211,jsonb_build_object('claim_token',pg_temp.v('claim')->>'claim_token','receipt',pg_temp.id(999)))$$,'42501','DOCTOR_ACCESS_DENIED','forged delivery receipt denied');
select is(pg_temp.ob('deliver',6200,5,6212,jsonb_build_object('claim_token',pg_temp.v('claim')->>'claim_token','receipt',pg_temp.v('accepted')->>'receipt'))->>'state','delivered','separate explicit synthetic delivery receipt');
select pg_temp.ob('enqueue',6300,0,6301,pg_temp.v('enqueue'));
select pg_temp.put('withdraw_claim',pg_temp.ob('claim',6300,1,6302));
select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(6102),1,'revoke_consent','{"source_ref":"Synthetic withdrawal after persisted queue"}',pg_temp.id(6303));
select is(pg_temp.ob('accept',6300,2,6304,jsonb_build_object('claim_token',pg_temp.v('withdraw_claim')->>'claim_token'))->>'blocker','consent_unavailable','M3-005 linked: persisted queue then withdrawal suppresses actual synthetic dispatch');
reset role;
select is((select count(*)::integer from doctor_private.synthetic_message_acceptances where message_id=pg_temp.id(6300)),0,'withdrawn queue never accepted');
select ok((select intent->>'consent_version'='1' and consent_id=pg_temp.id(6102) from public.message_outbox where id=pg_temp.id(6300)),'captured consent reference preserved');
-- Restore only run-owned fixtures to exercise independent branches of the state machine.
update public.patient_contact_consents set allowed=true,version=1,revoked_at=null where id=pg_temp.id(6102);
set local role authenticated;
select pg_temp.ob('enqueue',6400,0,6401,pg_temp.v('enqueue'));
reset role;update public.message_outbox set expires_at=clock_timestamp()-interval '1 second'where id=pg_temp.id(6400);set local role authenticated;
select is(pg_temp.ob('claim',6400,1,6402)->>'blocker','expired','expired message never claimed');
select pg_temp.ob('enqueue',6500,0,6501,pg_temp.v('enqueue'));
select pg_temp.put('timeout_claim',pg_temp.ob('claim',6500,1,6502));
select is(pg_temp.ob('timeout',6500,2,6503,jsonb_build_object('claim_token',pg_temp.v('timeout_claim')->>'claim_token'))->>'state','unknown','timeout is ambiguous, never safe retry');
select is(pg_temp.ob('reconcile',6500,3,6504)->>'blocker','acceptance_unknown','missing acceptance is not proof of rejection');
select throws_ok($$select pg_temp.ob('claim',6500,4,6505)$$,'40001','DOCTOR_OUTBOX_CONFLICT','unknown outcome cannot blindly resend');
select pg_temp.ob('enqueue',6600,0,6601,pg_temp.v('enqueue'));
select pg_temp.put('reject_claim',pg_temp.ob('claim',6600,1,6602));
select is(pg_temp.ob('reject',6600,2,6603,jsonb_build_object('claim_token',pg_temp.v('reject_claim')->>'claim_token'))->>'state','queued','definite nonacceptance permits bounded retry');
select throws_ok($$select pg_temp.ob('claim',6600,3,6604)$$,'40001','DOCTOR_OUTBOX_CONFLICT','backoff enforced');
reset role;update public.message_outbox set available_at=clock_timestamp()-interval '1 second'where id=pg_temp.id(6600);set local role authenticated;
select pg_temp.put('reject_claim2',pg_temp.ob('claim',6600,3,6605));
select is(pg_temp.ob('reject',6600,4,6606,jsonb_build_object('claim_token',pg_temp.v('reject_claim2')->>'claim_token'))->>'state','queued','second rejection retains one final retry');
reset role;update public.message_outbox set available_at=clock_timestamp()-interval '1 second'where id=pg_temp.id(6600);set local role authenticated;
select pg_temp.put('reject_claim3',pg_temp.ob('claim',6600,5,6607));
select is(pg_temp.ob('reject',6600,6,6608,jsonb_build_object('claim_token',pg_temp.v('reject_claim3')->>'claim_token'))->>'blocker','retry_exhausted','third actual rejection exhausts retry bound');
select throws_ok($$select pg_temp.ob('claim',6600,7,6609)$$,'40001','DOCTOR_OUTBOX_CONFLICT','exhausted work cannot claim again');
select ok(public.doctor_outbox(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)::text not like '%15550001234%','C03: status projection excludes destination');
select ok(public.doctor_outbox(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)::text not like '%receipt%','C03: status projection excludes delivery capability');
select is(public.doctor_outbox(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)->>'external_delivery','false','external delivery stays disabled');
select throws_ok($$select * from public.message_outbox$$,'42501',null,'direct outbox reads denied');
select throws_ok($$insert into doctor_private.synthetic_message_acceptances(practice_id,message_id,claim_token)values(pg_temp.practice(),pg_temp.id(6500),pg_temp.id(1))$$,'42501',null,'callback cannot forge private acceptance');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_outbox(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)$$,'42501','DOCTOR_ACCESS_DENIED','cross-doctor history denied');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.ob('enqueue',6700,0,6701,pg_temp.v('enqueue'))$$,'42501','DOCTOR_ACCESS_DENIED','read-only secretary cannot enqueue');
reset role;set local role service_role;
select throws_ok($$select public.doctor_outbox(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),0)$$,'42501',null,'ambient service role cannot operate synthetic queue');
reset role;
select is((select count(*)::integer from doctor_private.synthetic_message_acceptances),1,'no timeout/retry/withdrawal branch invents acceptance');
select * from finish();rollback;
